FILES = {'backend/pune_intelligence/__init__.py': '\nfrom .engine import build_location_intelligence\nfrom .location_network import load_locations\nfrom .langgraph_node import pune_innovation_node\n\n__all__ = ["build_location_intelligence", "load_locations", "pune_innovation_node"]\n', 'backend/pune_intelligence/location_network.py': '\nfrom pathlib import Path\nimport pandas as pd\n\nROOT = Path(__file__).resolve().parents[2]\n\nCANDIDATES = [\n    ROOT / "data" / "processed" / "pune_100_locations_mapped.csv",\n    ROOT / "data" / "processed" / "pune_100_locations.csv",\n]\n\ndef _find_col(df, names):\n    normalized = {str(c).strip().lower().replace(" ", "_"): c for c in df.columns}\n    for name in names:\n        key = name.lower().replace(" ", "_")\n        if key in normalized:\n            return normalized[key]\n    for c in df.columns:\n        key = str(c).strip().lower().replace(" ", "_")\n        if any(name.lower().replace(" ", "_") in key for name in names):\n            return c\n    return None\n\ndef load_locations():\n    path = next((p for p in CANDIDATES if p.exists()), None)\n    if path is None:\n        raise FileNotFoundError(\n            "Pune location master not found. Expected: "\n            + " or ".join(str(p) for p in CANDIDATES)\n        )\n    df = pd.read_csv(path)\n\n    name_col = _find_col(df, ["location", "location_name", "locality", "name", "place", "area"])\n    lat_col = _find_col(df, ["latitude", "lat"])\n    lon_col = _find_col(df, ["longitude", "lon", "lng"])\n    station_col = _find_col(df, ["representative_cpcb_station", "representative_station", "cpcb_station", "station"])\n\n    if name_col is None:\n        raise ValueError(f"No locality column found. Columns: {df.columns.tolist()}")\n\n    out = pd.DataFrame()\n    out["location"] = df[name_col].astype(str).str.strip()\n    out["latitude"] = pd.to_numeric(df[lat_col], errors="coerce") if lat_col else float("nan")\n    out["longitude"] = pd.to_numeric(df[lon_col], errors="coerce") if lon_col else float("nan")\n    out["representative_cpcb_station"] = (\n        df[station_col].astype(str).str.strip() if station_col else ""\n    )\n    out = out[out["location"].ne("")].drop_duplicates("location").reset_index(drop=True)\n    return out\n\ndef resolve_query(row):\n    try:\n        lat = float(row.get("latitude"))\n        lon = float(row.get("longitude"))\n        if pd.notna(lat) and pd.notna(lon):\n            return f"{lat},{lon}"\n    except Exception:\n        pass\n    return f"{row[\'location\']}, Pune, Maharashtra, India"\n', 'backend/pune_intelligence/engine.py': '\nimport math\n\ndef _num(v):\n    try:\n        if v is None or v == "":\n            return None\n        x = float(v)\n        return None if math.isnan(x) or math.isinf(x) else x\n    except (TypeError, ValueError):\n        return None\n\ndef _find(data, aliases):\n    if isinstance(data, dict):\n        for k, v in data.items():\n            nk = str(k).lower().replace(".", "").replace("-", "_").replace(" ", "_")\n            if nk in aliases:\n                return v\n        for v in data.values():\n            x = _find(v, aliases)\n            if x is not None:\n                return x\n    elif isinstance(data, list):\n        for v in data:\n            x = _find(v, aliases)\n            if x is not None:\n                return x\n    return None\n\ndef pollutant(report, name):\n    groups = {\n        "pm25": {"pm25", "pm2_5", "pm25_current", "current_pm25"},\n        "pm10": {"pm10", "pm10_current"},\n        "no2": {"no2"},\n        "so2": {"so2"},\n        "co": {"co"},\n        "o3": {"o3"},\n    }\n    return _num(_find(report, groups.get(name, {name})))\n\ndef weather(report, name):\n    groups = {\n        "wind_speed": {"wind_speed", "wind_kph", "wind_mph", "wind_mps"},\n        "rainfall": {"rainfall", "precip_mm", "precipitation", "rain_mm"},\n        "temperature": {"temperature", "temp_c", "temp"},\n        "humidity": {"humidity"},\n    }\n    return _num(_find(report, groups.get(name, {name})))\n\ndef next_pm25(report):\n    return _num(_find(report, {\n        "predicted_pm25_next_1h", "next_hour_pm25", "pm25_next_hour", "predicted_pm25"\n    }))\n\ndef _score(v, cuts):\n    if v is None:\n        return 0.0\n    if v <= cuts[0]:\n        return 0.0\n    for i in range(1, len(cuts)):\n        lo, hi = cuts[i-1], cuts[i]\n        if v <= hi:\n            return ((v-lo)/max(hi-lo, 1e-9)) * (i/(len(cuts)-1)) * 100.0\n    return 100.0\n\ndef factor_scores(report):\n    pm25, pm10 = pollutant(report, "pm25"), pollutant(report, "pm10")\n    no2, so2, co = pollutant(report, "no2"), pollutant(report, "so2"), pollutant(report, "co")\n    wind, rain = weather(report, "wind_speed"), weather(report, "rainfall")\n\n    dust = max(_score(pm10, [50,100,150,250]), _score(pm25, [30,60,90,120]))\n    traffic = max(_score(no2, [40,80,180,280]), _score(co, [1,2,5,10]))\n    industry = _score(so2, [40,80,180,380])\n    stagnation = 0.0 if wind is None else max(0.0, min((4-wind)/4*100, 100))\n    rain_scavenging = 0.0 if rain is None else max(0.0, min(rain/10*100, 100))\n\n    return {\n        "particulate_dust": round(dust, 1),\n        "traffic_combustion": round(traffic, 1),\n        "industrial_sulfur": round(industry, 1),\n        "meteorological_stagnation": round(stagnation, 1),\n        "rain_scavenging": round(rain_scavenging, 1),\n    }\n\ndef environmental_score(report):\n    pm25, pm10, no2 = pollutant(report, "pm25"), pollutant(report, "pm10"), pollutant(report, "no2")\n    wind, rain = weather(report, "wind_speed"), weather(report, "rainfall")\n\n    c = {\n        "pm25": _score(pm25, [30,60,90,120,250]),\n        "pm10": _score(pm10, [50,100,150,250,350]),\n        "no2": _score(no2, [40,80,180,280,400]),\n        "wind_stagnation": 0.0 if wind is None else max(0.0, min((4-wind)/4*100,100)),\n    }\n    value = c["pm25"]*0.40 + c["pm10"]*0.20 + c["no2"]*0.15 + c["wind_stagnation"]*0.20\n    if rain is not None and rain >= 2:\n        value -= 10\n    value = max(0, min(value, 100))\n\n    band = (\n        "Low" if value < 20 else\n        "Guarded" if value < 40 else\n        "Elevated" if value < 60 else\n        "High" if value < 80 else "Critical"\n    )\n    return {\n        "score": round(value, 1),\n        "band": band,\n        "components": {k: round(v, 1) for k, v in c.items()},\n        "note": "Comparative Pune locality score; not official AQI."\n    }\n\ndef _actions(f):\n    a = []\n    if f["particulate_dust"] >= 40:\n        a.append({"priority":"HIGH","action":"Road-dust suppression and construction-dust compliance checks","targets":["PM10","PM2.5"]})\n    if f["traffic_combustion"] >= 40:\n        a.append({"priority":"HIGH","action":"Traffic-corridor and idling/emission enforcement","targets":["NO2","PM2.5"]})\n    if f["industrial_sulfur"] >= 40:\n        a.append({"priority":"HIGH","action":"Industrial-emission inspection and compliance review","targets":["SO2","PM2.5"]})\n    if f["meteorological_stagnation"] >= 50:\n        a.append({"priority":"MEDIUM","action":"Increase monitoring during weak-dispersion windows","targets":["PM2.5","PM10"]})\n    if not a:\n        a.append({"priority":"MEDIUM","action":"Maintain monitoring and observe the forecast trend","targets":["Ambient air quality"]})\n    return a\n\ndef simulate(report, selected=None):\n    base = pollutant(report, "pm25")\n    if base is None:\n        return {"available": False, "reason": "PM2.5 unavailable."}\n    f = factor_scores(report)\n    if selected is None:\n        selected = []\n        if f["particulate_dust"] >= 40: selected.append("road_dust_control")\n        if f["traffic_combustion"] >= 40: selected.append("traffic_management")\n        if f["industrial_sulfur"] >= 40: selected.append("industrial_control")\n        if not selected: selected = ["monitoring"]\n\n    effects = {\n        "road_dust_control": (0.04,0.12),\n        "construction_control": (0.03,0.10),\n        "traffic_management": (0.03,0.09),\n        "industrial_control": (0.04,0.12),\n        "waste_burning_control": (0.05,0.15),\n        "monitoring": (0.00,0.03),\n    }\n    lo = min(sum(effects.get(x,(0,0))[0] for x in selected), 0.30)\n    hi = min(sum(effects.get(x,(0,0))[1] for x in selected), 0.45)\n    return {\n        "available": True,\n        "baseline_pm25": round(base,2),\n        "selected_interventions": selected,\n        "reduction_low_pct": round(lo*100,1),\n        "reduction_high_pct": round(hi*100,1),\n        "estimated_pm25_low": round(max(0, base*(1-hi)),2),\n        "estimated_pm25_high": round(max(0, base*(1-lo)),2),\n        "confidence": "Moderate" if len(selected) <= 1 else "Moderate-Low",\n        "methodology": "Heuristic scenario range; not a causal policy counterfactual.",\n    }\n\ndef build_location_intelligence(report, location, representative_station=None):\n    factors = factor_scores(report)\n    ranked = sorted(factors.items(), key=lambda x: x[1], reverse=True)\n    nxt = next_pm25(report)\n    cur = pollutant(report, "pm25")\n\n    trend = None\n    if cur is not None and nxt is not None:\n        d = nxt-cur\n        trend = {\n            "current_pm25": round(cur,2),\n            "next_hour_pm25": round(nxt,2),\n            "delta": round(d,2),\n            "trend": "Rise" if d >= 2 else "Fall" if d <= -2 else "Stable"\n        }\n\n    return {\n        "innovation": "Pune Locality Environmental Intelligence",\n        "location": location,\n        "scope": "100+ Pune locality network",\n        "representative_cpcb_station": representative_station,\n        "environmental_score": environmental_score(report),\n        "factor_fingerprint": {\n            "top_factors": [{"factor":k,"score":v} for k,v in ranked if v>0][:6],\n            "note": "Indicators, not definitive source apportionment."\n        },\n        "next_hour_signal": trend or {"available": False},\n        "policy_to_action": {\n            "actions": _actions(factors),\n            "note": "Condition-based action mapping, not causal policy impact."\n        },\n        "intervention_simulator": simulate(report),\n    }\n', 'backend/pune_intelligence/orchestrator.py': '\nimport json\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\nfrom pathlib import Path\nimport pandas as pd\n\nfrom backend.services.weather_intelligence import get_weather_report\nfrom backend.ml.forecasting.predict_forecast import get_xgboost_forecast\nfrom backend.pune_intelligence.location_network import load_locations, resolve_query\nfrom backend.pune_intelligence.engine import build_location_intelligence\n\nROOT = Path(__file__).resolve().parents[2]\nOUT_DIR = ROOT / "data" / "reports" / "pune_network"\nOUT_JSON = OUT_DIR / "pune_100_plus_intelligence.json"\nOUT_CSV = OUT_DIR / "pune_100_plus_summary.csv"\n\ndef _one(row):\n    location = str(row["location"])\n    query = resolve_query(row)\n    try:\n        env = get_weather_report(query, days=1)\n    except Exception as exc:\n        return {"location":location,"status":"weather_error","error":str(exc)}\n\n    station = str(row.get("representative_cpcb_station") or "").strip()\n    xgb = {}\n    if station and station.lower() not in {"nan","none"}:\n        try:\n            xgb = get_xgboost_forecast(station)\n        except Exception as exc:\n            xgb = {"available":False,"reason":str(exc)}\n    env["xgboost"] = xgb\n\n    intel = build_location_intelligence(env, location, station or None)\n    return {\n        "location":location,\n        "query":query,\n        "latitude":row.get("latitude"),\n        "longitude":row.get("longitude"),\n        "representative_cpcb_station":station or None,\n        "status":"ok",\n        "environment":env,\n        "intelligence":intel,\n    }\n\ndef build_network(workers=4):\n    locations = load_locations()\n    if len(locations) < 100:\n        raise ValueError(f"Only {len(locations)} Pune locations found; need 100+.")\n\n    rows = locations.to_dict("records")\n    results = []\n    with ThreadPoolExecutor(max_workers=max(1,min(workers,8))) as pool:\n        futures = [pool.submit(_one,row) for row in rows]\n        for i,f in enumerate(as_completed(futures),1):\n            r = f.result()\n            results.append(r)\n            print(f"[{i}/{len(rows)}] {r.get(\'location\')} -> {r.get(\'status\')}")\n\n    ok = [r for r in results if r.get("status") == "ok"]\n    scores = [r["intelligence"]["environmental_score"]["score"] for r in ok if r["intelligence"]["environmental_score"].get("score") is not None]\n    for r in ok:\n        if scores:\n            s = r["intelligence"]["environmental_score"]["score"]\n            r["intelligence"]["pune_relative_percentile"] = round(100*sum(x <= s for x in scores)/len(scores),1)\n\n    OUT_DIR.mkdir(parents=True, exist_ok=True)\n    payload = {\n        "project":"Pune Locality Environmental Intelligence",\n        "location_count":len(rows),\n        "successful_locations":len(ok),\n        "failed_locations":len(rows)-len(ok),\n        "locations":results,\n    }\n    OUT_JSON.write_text(json.dumps(payload,indent=2,ensure_ascii=False,default=str), encoding="utf-8")\n\n    summary=[]\n    for r in results:\n        intel=r.get("intelligence",{})\n        ef=intel.get("environmental_score",{})\n        top=intel.get("factor_fingerprint",{}).get("top_factors",[])\n        summary.append({\n            "location":r.get("location"),\n            "latitude":r.get("latitude"),\n            "longitude":r.get("longitude"),\n            "representative_cpcb_station":r.get("representative_cpcb_station"),\n            "status":r.get("status"),\n            "environmental_score":ef.get("score"),\n            "risk_band":ef.get("band"),\n            "top_factor":top[0]["factor"] if top else None,\n            "pune_relative_percentile":intel.get("pune_relative_percentile")\n        })\n    pd.DataFrame(summary).to_csv(OUT_CSV,index=False)\n    return payload\n', 'backend/pune_intelligence/langgraph_node.py': '\nfrom backend.pune_intelligence.location_network import load_locations\nfrom backend.pune_intelligence.engine import build_location_intelligence\n\ndef pune_innovation_node(state):\n    location = state.get("location") or state.get("resolved_location") or state.get("city")\n    report = state.get("environment_report") or state.get("environment") or state.get("report")\n\n    if not location or not isinstance(report, dict):\n        return {"pune_innovation":{"available":False,"reason":"Pune location or environment report unavailable."}}\n\n    df = load_locations()\n    q = str(location).strip().lower()\n    exact = df[df["location"].str.lower() == q]\n    if exact.empty:\n        exact = df[df["location"].str.lower().str.contains(q,regex=False,na=False)]\n\n    if exact.empty:\n        return {"pune_innovation":{"available":False,"reason":f"{location} is not in the Pune 100+ location network."}}\n\n    row = exact.iloc[0].to_dict()\n    station = str(row.get("representative_cpcb_station") or "").strip()\n\n    return {\n        "pune_innovation": {\n            "available": True,\n            **build_location_intelligence(report,str(row["location"]),station or None),\n        }\n    }\n', 'scripts/pune_location_intelligence.py': '\nimport argparse\nimport json\nfrom backend.pune_intelligence.location_network import load_locations, resolve_query\nfrom backend.services.weather_intelligence import get_weather_report\nfrom backend.ml.forecasting.predict_forecast import get_xgboost_forecast\nfrom backend.pune_intelligence.engine import build_location_intelligence\n\ndef main():\n    parser=argparse.ArgumentParser()\n    parser.add_argument("location")\n    args=parser.parse_args()\n\n    df=load_locations()\n    q=args.location.strip().lower()\n    rows=df[df["location"].str.lower()==q]\n    if rows.empty:\n        rows=df[df["location"].str.lower().str.contains(q,regex=False,na=False)]\n    if rows.empty:\n        raise SystemExit(f"{args.location} not found in Pune 100+ location network.")\n\n    row=rows.iloc[0].to_dict()\n    env=get_weather_report(resolve_query(row), days=1)\n    station=str(row.get("representative_cpcb_station") or "").strip()\n    if station:\n        try:\n            env["xgboost"]=get_xgboost_forecast(station)\n        except Exception as exc:\n            env["xgboost"]={"available":False,"reason":str(exc)}\n\n    result=build_location_intelligence(env,str(row["location"]),station or None)\n    result["environment"]=env\n    print(json.dumps(result,indent=2,ensure_ascii=False,default=str))\n\nif __name__=="__main__":\n    main()\n'}

